package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Assigns a shared {@code householdId} when a create request opts in with
 * {@code sharesHousehold: true}, joining an existing owner at the same household — the
 * same {@code lastName} (compared case-insensitively with collapsed whitespace) and the
 * same {@code address} in its normalized form (see {@link AddressNormalizer}), matching
 * {@link EnsureUniqueHousehold}.
 *
 * <p>The identifier is derived deterministically from the normalized last name and
 * address, so every owner of a household computes the same value regardless of creation
 * order — a stable shared identifier. Existing same-household owners that do not yet
 * carry one are back-filled so both sides share it.
 *
 * <p>Runs after {@link BuildOwner} (which produces the {@link Owner}) and before
 * {@link SaveOwner}; it mutates the built owner in place (see {@code @Val} semantics).
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
            OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(owner.getLastName());
        String address = normalizeAddress(owner.getAddress());
        String householdId = householdId(lastName, address);
        owner.setHouseholdId(householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(normalizeAddress(existing.getAddress()))
                    && existing.getHouseholdId() == null) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }

    /** Stable 16-char upper-case hex identifier over the normalized last name and address. */
    private static String householdId(String lastName, String address) {
        return sha256hex(lastName + "|" + address).substring(0, 16).toUpperCase();
    }

    private static String sha256hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase();
    }

    /** The canonical address form (see {@link AddressNormalizer}); never {@code null}. */
    private static String normalizeAddress(String value) {
        String normalized = AddressNormalizer.normalize(value);
        return normalized == null ? "" : normalized;
    }
}
===== TelephoneE164 =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Normalizes a telephone number to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
 * form: a leading {@code '+'} followed by 8 to 15 digits.
 *
 * <p>Rules:
 * <ul>
 *   <li>spaces, dashes and brackets are stripped;</li>
 *   <li>when the input already carries a leading {@code '+'} (a country code), it is kept
 *       and the remaining digits are used verbatim;</li>
 *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
 *       dropped from the national digits;</li>
 *   <li>the result must have 8 to 15 digits after the {@code '+'}, else it is not valid E.164;</li>
 *   <li>the national-number length must match the country code — {@code '+61'} requires exactly 9
 *       national digits and {@code '+1'} requires exactly 10; a wrong length is not valid.</li>
 * </ul>
 *
 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
 * becomes {@code "+6421123456"}.
 */
public final class TelephoneE164 {

    private TelephoneE164() {
    }

    /**
     * Returns the E.164 form of {@code raw}, or {@code null} if it cannot form a valid E.164
     * number.
     */
    public static String normalize(String raw) {
        if (raw == null) {
            return null;
        }
        boolean hasCountryCode = raw.strip().startsWith("+");
        String digits = raw.replaceAll("\\D", "");
        String e164Digits;
        if (hasCountryCode) {
            e164Digits = digits;
        }
        else {
            String national = digits.startsWith("0") ? digits.substring(1) : digits;
            e164Digits = "61" + national;
        }
        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
            return null;
        }
        if (!hasValidNationalLength(e164Digits)) {
            return null;
        }
        return "+" + e164Digits;
    }

    /**
     * Checks the national-number length against the country code. {@code '+61'} requires exactly 9
     * national digits and {@code '+1'} requires exactly 10; other country codes are not constrained
     * here beyond the overall 8-to-15 E.164 length.
     */
    private static boolean hasValidNationalLength(String e164Digits) {
        if (e164Digits.startsWith("61")) {
            return e164Digits.length() - 2 == 9;
        }
        if (e164Digits.startsWith("1")) {
            return e164Digits.length() - 1 == 10;
        }
        return true;
    }
}
